'use strict';
const loginContext=()=>{const params=new URLSearchParams((route().split('?')[1]||''));const requested=params.get('org');return requested&&db.orgs.some(o=>o.id===requested)?requested:null};
function currentStoreContext(){if(currentRoute.startsWith('/institution/'))return currentRoute.split('/')[2];if(currentRoute.startsWith('/product/'))return product(currentRoute.split('/')[2])?.org||null;return loginContext()||db.buyerOrg||null}
function mallTitle(id){return shopSettings(id).mallTitle||org(id).name+'몰'}
function institutionLogo(id){const o=org(id);return o.logoUploadId&&uploadedImages.has(o.logoUploadId)?uploadedImages.get(o.logoUploadId):'/assets/org-logos/'+(o.logoPreset||'logo-'+(db.orgs.findIndex(x=>x.id===id)%4+1))+'.svg'}
function ownProfileImage(cls=''){const p=accountProfile();return p.uploadId&&uploadedImages.has(p.uploadId)?`<img class="character-avatar custom-profile ${cls}" src="${uploadedImages.get(p.uploadId)}" alt="나의 프로필 이미지">`:avatarHTML(p.avatar,cls)}
function loginRoute(orgId,signup=false){return '#/'+(signup?'signup':'login')+(orgId?'?org='+encodeURIComponent(orgId):'')}
function testLoginPanel(orgId=null){if(orgId)return `<section class="store-login-card"><div class="store-login-identity"><img src="${institutionLogo(orgId)}" alt="${esc(org(orgId).name)} 로고"><div><small>OUR STORE, OUR COMMUNITY</small><h3>${esc(mallTitle(orgId))} 회원</h3><p>후원자·자원봉사자와 함께하는 기분 좋은 쇼핑</p></div></div><div class="store-login-actions"><a class="primary-btn green" href="${loginRoute(orgId)}">기관몰 로그인·가입</a>${btn('test-login','구매자 테스트 로그인','secondary-btn',`data-role="buyer" data-org="${orgId}"`)}</div>${db.role==='buyer'&&db.buyerOrg===orgId?`<p class="membership-state">${icon('check')} ${esc(db.profile.name)}님 · 이 기관몰 소속 구매자 <a href="#/my">마이 쇼핑</a></p>`:'<p class="login-caption">이 기관몰에 소속된 구매자 계정으로 이용합니다.</p>'}</section>`;return `<section class="main-login-panel"><div class="split-row"><div><p class="section-overline">YOUR BANGGEUT WORKSPACE</p><h2>나에게 맞는 방긋 시작하기</h2></div><a href="#/login" class="pill-btn">로그인·회원가입 ${icon('arrow')}</a></div><p>기부자부터 기관 운영자까지, 각 계정을 바로 체험해 보세요.</p><div class="test-account-grid">${[['individual','user','개인 기부자'],['company','building','기업 기부자'],['agency','shop','기관 관리자'],['admin','settings','최고 관리자']].map(([role,i,label])=>btn('test-login',`<span>${icon(i)}</span><b>${label}</b><small>테스트 로그인 ${icon('arrow')}</small>`,'test-account-button',`data-role="${role}" aria-label="${label} 테스트 로그인"`)).join('')}</div><p class="login-caption">테스트 버튼은 가상 계정으로 즉시 로그인합니다.</p></section>`}
function providerButtons(id){return `<div class="provider-buttons">${btn('social-login','<span class="social-icon kakao-icon">●</span>카카오로 계속하기','provider-button kakao',`data-provider="카카오" data-org="${id||''}"`)}${btn('social-login','<span class="social-icon">N</span>네이버로 계속하기','provider-button naver',`data-provider="네이버" data-org="${id||''}"`)}</div>`}
function accountPage(signup=false){const id=loginContext();return header()+`<section class="account-page"><div class="account-brand">${id?`<img src="${institutionLogo(id)}" alt="${esc(org(id).name)} 로고">`:'<img src="/assets/brand/banggeut-icon.png" alt="방긋마켓 꽃 미소 로고">'}<span class="section-overline">${id?'OUR STORE COMMUNITY':'A LITTLE GOOD, A BIG SMILE'}</span><h1>${id?esc(mallTitle(id)):'방긋마켓'}<br><em>${signup?'함께해서 더 방긋.':'다시 만나서 방긋.'}</em></h1><p>${id?'후원자·자원봉사자와 함께하는 우리 기관몰.<br>이 기관에 소속된 구매자로 이용해 주세요.':'당신의 쇼핑과 나눔을 한곳에서.<br>반가운 마음으로 시작해 보세요.'}</p></div>${providerButtons(id)}<div class="login-divider"><span>이메일로 ${signup?'가입하기':'로그인'}</span></div><form id="email-account-form" data-mode="${signup?'signup':'login'}" data-org="${id||''}">${signup?`${field(id?'구매자 이름':'이름·기업명','name','','text','required maxlength="40" autocomplete="nickname"')}${id?selectField('기관과의 관계','membership',[['후원자','후원자'],['자원봉사자','자원봉사자'],['후원자·자원봉사자','후원자·자원봉사자'],['일반 구매자','일반 구매자']],'후원자'):selectField('가입 유형','role',[['buyer','일반 구매자'],['individual','개인 기부자'],['company','기업 기부자']],'buyer')}`:''}${field('이메일','email','','email','required maxlength="120" autocomplete="username" placeholder="demo@example.com"')}${field('비밀번호','password','','password',`required minlength="8" maxlength="128" autocomplete="${signup?'new-password':'current-password'}" placeholder="체험용 비밀번호 8자 이상"`)}${signup?field('비밀번호 확인','confirm','','password','required minlength="8" maxlength="128" autocomplete="new-password"'):''}${signup?'<label class="check-line"><input type="checkbox" name="consent" required>체험용 정보를 이 브라우저에 저장하는 데 동의합니다.</label>':''}<p class="account-form-error" role="alert" hidden></p><button class="primary-btn green full" type="submit">${signup?'이메일 가입 체험':'이메일 로그인 체험'}</button></form><p class="account-switch">${signup?'이미 체험 계정이 있나요?':'처음 오셨나요?'} <a href="${loginRoute(id,!signup)}">${signup?'이메일 로그인':'이메일로 회원가입'}</a></p>${id?btn('test-login',icon('smile')+' 구매자 테스트 로그인','secondary-btn full',`data-role="buyer" data-org="${id}"`):`<div class="account-test-links">${[['individual','개인 기부자'],['company','기업 기부자'],['agency','기관 관리자'],['admin','최고 관리자']].map(([role,label])=>btn('test-login',label+' 테스트','pill-btn',`data-role="${role}"`)).join('')}</div>`}<div class="account-prototype-note">${icon('info')}<p>현재는 브라우저에만 저장되는 로그인 체험입니다. 실제 개인정보나 사용 중인 비밀번호를 입력하지 마세요. 카카오·네이버 실제 인증은 운영 연동 전입니다.</p></div><a class="account-back" href="${id?'#/institution/'+id:'#/'}">${icon('back')} ${id?'기관몰':'방긋마켓'}로 돌아가기</a></section>`+bottomNav()}
function enterAccount(session){const guestCart=!db.role?structuredClone(db.cart):[];MarketCore.activateAccount(db,session.role,undefined,session);if(session.role==='buyer'&&guestCart.length&&!db.cart.length)db.cart=guestCart;if(session.kind==='email'){db.profile={...db.profile,name:session.name,email:session.email}}ensureDesignData();save();closeModal();consoleSection='dashboard';const destination=session.role==='buyer'?(session.buyerOrg?'/institution/'+session.buyerOrg:'/my'):'/console';if(route()===destination)render(true);else location.hash=destination;toast(session.buyerOrg?mallTitle(session.buyerOrg)+' 구매자로 로그인했습니다.':roleLabels[session.role]+' 계정으로 로그인했습니다.')}
function memberDirectory(){const ids=merchantOrgIds(),members=db.storeMembers.filter(m=>ids.includes(m.org));return consoleTitle(db.role==='admin'?'기관몰 구매자·후원자':'우리 기관몰 구매자·후원자','이 기관몰에서 가입하거나 테스트 로그인한 구매자입니다.')+`<div class="stat-grid">${statCard('기관몰 가입·체험 회원',members.length+'명','현재 브라우저 기록',true)}${statCard('자원봉사 참여',members.filter(m=>m.membership.includes('자원봉사자')).length+'명','회원 가입 시 선택')}</div><div class="data-list">${members.map(m=>`<div class="data-row">${ownMemberAvatar(m)}<div class="data-row-content"><h3>${esc(m.name)}</h3><p>${esc(org(m.org).name)} · ${esc(m.membership)}<br>${esc(m.provider)} · 가입 ${esc(m.createdAt.slice(0,10))}</p></div>${status(m.status)}</div>`).join('')||empty('아직 가입한 구매자가 없어요','기관몰의 구매자 테스트 로그인으로 가입 흐름을 확인해 보세요.')}</div>`}
function ownMemberAvatar(m){const p=db.accountProfiles[m.accountKey];return avatarHTML(p?.avatar||1)}
function logoManagerCard(id){return `<section class="institution-logo-manager"><div class="store-login-identity"><img src="${institutionLogo(id)}" alt="기관 로고 미리보기"><div><h3>기관 로고와 몰 이름</h3><p>기관 로고와 담당자의 프로필은 따로 관리합니다.</p></div></div><form id="store-brand-form" data-org="${id}">${field('기관 쇼핑몰 이름','mallTitle',mallTitle(id),'text','required maxlength="50"')}<button class="primary-btn green full">몰 이름 저장</button></form><div class="button-group mt-20"><label class="secondary-btn image-upload-label">${icon('camera')} 기관 로고 업로드<input type="file" accept="image/png,image/jpeg,image/webp" id="institution-logo-upload" data-org="${id}" hidden></label>${btn('institution-logo-reset','기본 로고 사용','secondary-btn',`data-org="${id}"`)}</div><p class="small muted">기본 표시는 예시 기관 로고이며, 실제 기관 로고로 교체할 수 있습니다.</p></section>`}
function initAccounts(){AccountCore.ensure(db);for(const role of ['agency','admin'])menus[role].splice(menus[role].findIndex(m=>m[0]==='customers'),0,['shoppers',role==='admin'?'기관몰 구매자':'구매자·후원자']);
 const originalHeader=header;header=function(compact=false){let html=originalHeader(compact).replace('data-action="roles"','data-action="account-entry"');if(db.role)html=html.replace(/<span class="character-avatar animal-avatar header-avatar"[^>]*><\/span>/,ownProfileImage('header-avatar'));return html};
 const originalHome=home;home=function(){return originalHome().replace('<div class="shortcuts">',testLoginPanel()+'<div class="shortcuts">')};
 const originalOrg=orgPage;orgPage=function(id){const o=org(id);return originalOrg(id).replace('data-action="roles"','data-action="account-entry"').replace('<section class="mall-hero"',testLoginPanel(o.id)+'<section class="mall-hero"')};
 const originalProfile=profileSettings;profileSettings=function(){const p=accountProfile();return originalProfile().replace(avatarHTML(p.avatar,'large'),ownProfileImage('large')).replace('</section>',`<div class="button-group mt-20"><label class="secondary-btn image-upload-label">${icon('camera')} 내 사진 업로드<input id="account-profile-upload" type="file" accept="image/png,image/jpeg,image/webp" hidden></label>${p.uploadId?btn('profile-image-reset','기본 캐릭터 사용','secondary-btn'):''}</div></section>`)};
 const originalMy=myPage;myPage=function(){let html=originalMy();const ownDonations=db.donations.filter(d=>d.ownerAccount===MarketCore.accountId(db));if(db.role==='buyer'&&ownDonations.length)html=html.replace('<div class="section-heading"><h2 style="font-size:18px">최근 주문</h2>',`<div class="section-heading"><h2 style="font-size:18px">나의 기부 신청</h2></div>${donationList(ownDonations)}<div class="section-heading mt-20"><h2 style="font-size:18px">최근 주문</h2>`);const title=db.role==='buyer'&&db.buyerOrg?`<div class="my-membership-banner"><img src="${institutionLogo(db.buyerOrg)}" alt="기관 로고"><span><small>MY STORE MEMBERSHIP</small><strong>${esc(mallTitle(db.buyerOrg))}</strong><b>${esc(db.session?.membership||'후원자')} · 소속 구매자</b></span><a href="#/institution/${db.buyerOrg}" class="pill-btn">기관몰 가기</a></div>`:'';html=html.replace('<section class="section" style="padding-top:0">','<section class="section" style="padding-top:0">'+title);return html.replace(avatarHTML(accountProfile().avatar,'large'),ownProfileImage('large'))};
 const originalContent=consoleContent;consoleContent=function(){if(consoleSection==='shoppers'&&canOperate())return memberDirectory();let html=originalContent();if(consoleSection==='mall'&&mallEditorTab==='overview'&&canOperate()&&!(db.role==='admin'&&marketScope==='all'))html=html.replace('<form id="merchant-shop-form"',logoManagerCard(selectedStore())+'<form id="merchant-shop-form"');return html};
 const originalRender=render;render=function(reset=false){AccountCore.ensure(db);if(['/login','/signup'].includes(route().split('?')[0])){currentRoute=route();$('#app').innerHTML=accountPage(currentRoute.startsWith('/signup'));rail();document.body.classList.remove('institution-view');applyAppearance();document.title=(loginContext()?mallTitle(loginContext())+' · ':'')+'로그인 · 방긋마켓';if(reset)window.scrollTo(0,0)}else originalRender(reset);if(currentRoute.startsWith('/institution/')){const id=org(currentRoute.split('/')[2]).id;document.querySelectorAll('.org-logo-fixed').forEach(el=>{el.innerHTML=`<img src="${institutionLogo(id)}" alt="${esc(org(id).name)} 로고">`});if(db.role==='buyer'&&db.buyerOrg!==id){const entry=$('.mall-header [data-action="account-entry"]');if(entry){entry.innerHTML=icon('user');entry.setAttribute('aria-label','이 기관몰 로그인')}}const title=$('.mall-header-brand strong');if(title)title.textContent=mallTitle(id);const small=$('.mall-header-brand small');if(small)small.textContent='방긋마켓과 함께하는 기관 쇼핑몰';document.title=mallTitle(id)+' · 방긋마켓';const side=$('.institution-side-brand strong');if(side)side.textContent=mallTitle(id)}document.querySelectorAll('.bottom-nav a').forEach(a=>{a.toggleAttribute('aria-current',a.classList.contains('active'));if(a.classList.contains('active'))a.setAttribute('aria-current','page')})};
 Object.assign(actions,{
 'account-entry':()=>{const id=currentStoreContext();if(!db.role||id&&db.role==='buyer'&&db.buyerOrg!==id){location.hash=loginRoute(id).slice(1);return}openModal('나의 방긋 계정',`<div class="account-menu-profile">${ownProfileImage('large')}<div><h3>${esc(db.profile.name)}</h3><p>${esc(roleLabels[db.role])}${db.buyerOrg?' · '+esc(mallTitle(db.buyerOrg)):''}</p></div></div><div class="account-menu-actions"><a href="#/my" class="primary-btn green full" data-action="close-modal">마이 쇼핑</a>${db.role!=='buyer'?'<a href="#/console" class="secondary-btn full" data-action="close-modal">내 콘솔</a>':''}<a href="#/profile" class="secondary-btn full" data-action="close-modal">프로필 설정</a><a href="${loginRoute(id)}" class="secondary-btn full" data-action="close-modal">다른 계정으로 로그인</a>${btn('logout','로그아웃','secondary-btn full')}</div>`)},
 'test-login':el=>{const role=el.dataset.role,id=el.dataset.org||null;if(!roleLabels[role])return;if(role==='agency'&&id)db.orgId=id;const session={kind:'test',role,buyerOrg:role==='buyer'?id:null,membership:role==='buyer'?'후원자':'',accountKey:role==='buyer'&&id?'buyer:'+id:role==='agency'?'agency:'+db.orgId:role};enterAccount(session);AccountCore.join(db,id,session.accountKey,db.profile.name,session.membership);save()},
 'social-login':el=>{const provider=el.dataset.provider,id=el.dataset.org||null;openModal(provider+' 로그인 연결 안내',`<div class="provider-connect-note">${icon('shield')}<h3>${esc(provider)} 실제 인증 연결 전입니다.</h3><p>현재 사이트에서는 ${esc(provider)} 계정 정보를 요청하지 않습니다. 운영 서비스의 인증 설정과 콜백 연결이 완료되면 사용할 수 있습니다.</p>${id?btn('test-login','기관몰 구매자 테스트 로그인','primary-btn green full',`data-role="buyer" data-org="${id}"`):'<a href="#/login" class="primary-btn green full" data-action="close-modal">이메일·테스트 로그인 보기</a>'}</div>`)},
 'profile-image-reset':()=>{delete accountProfile().uploadId;save();render();toast('기본 캐릭터로 변경했습니다.')},
 'institution-logo-reset':el=>{if(!isManagedOrg(el.dataset.org))return;delete org(el.dataset.org).logoUploadId;save();render();toast('기관 기본 로고로 변경했습니다.')}
 });
 const originalLogout=actions.logout;actions.logout=()=>{closeModal();originalLogout()};
 for(const key of ['avatar-commit','avatar-random-now']){const original=actions[key];actions[key]=()=>{delete accountProfile().uploadId;original()}};
 document.addEventListener('submit',async e=>{const f=e.target;if(f.id==='store-brand-form'){e.preventDefault();if(!isManagedOrg(f.dataset.org))return;const name=new FormData(f).get('mallTitle').trim();if(!name){toast('몰 이름을 입력해 주세요.');return}shopSettings(f.dataset.org).mallTitle=name;save();render();toast('기관몰 이름을 저장했습니다.')}if(f.id!=='email-account-form')return;e.preventDefault();if(f.dataset.busy)return;f.dataset.busy='true';const submit=f.querySelector('button[type="submit"]'),error=f.querySelector('.account-form-error');submit.disabled=true;error.hidden=true;try{const values=Object.fromEntries(new FormData(f)),input={...values,org:f.dataset.org||null};const session=await (f.dataset.mode==='signup'?AccountCore.register(db,input):AccountCore.login(db,input));enterAccount(session)}catch(err){error.textContent=err.message;error.hidden=false;save()}finally{if(f.isConnected){delete f.dataset.busy;submit.disabled=false}}});
 document.addEventListener('change',async e=>{const input=e.target;if(!['account-profile-upload','institution-logo-upload'].includes(input.id))return;const file=input.files?.[0];if(!file)return;const key=accountKey(),id=input.dataset.org;if(id&&!isManagedOrg(id))return;try{const uploadId=await storeUploadedImage(file);if(id){if(!isManagedOrg(id))return;org(id).logoUploadId=uploadId}else{if(key!==accountKey())return;accountProfile().uploadId=uploadId}save();render();toast(id?'기관 로고를 저장했습니다.':'내 프로필 이미지를 저장했습니다.')}catch(err){toast(err.message)}});
 // Authentication remains a clearly labelled prototype; no provider tokens are stored in the browser.
 save();
}
